pub fn trace_allwinner_ahci_mem_write(_s: *mut (), _a: *mut (), _addr: u64, _val: u64, _size: std::ffi::c_uint)
{
    if trace_event_state_is_enabled(unsafe { _TRACE_ALLWINNER_AHCI_MEM_WRITE_DSTATE}) {
        let format_string = c"allwinner_ahci_mem_write ahci(%p): write a=%p addr=0x%llx val=0x%llx, size=%d\n";
        if (unsafe { bindings::qemu_loglevel } & bindings::LOG_TRACE) != 0 {
            unsafe { bindings::qemu_log(format_string.as_ptr() as *const c_char, _s /* as *mut () */, _a /* as *mut () */, _addr /* as u64 */, _val /* as u64 */, _size /* as std::ffi::c_uint */);}
        }
    }
}
